package com.nthexperience.desktop;
import org.junit.Test;import org.json.*;import java.util.*;import static org.junit.Assert.*;
public class TaskManagerStateTest {
 @Test public void measuredRatesRejectFirstSamplesResetsAndInvalidIntervals(){assertTrue(Float.isNaN(TaskManagerState.rate(100,-1,1000)));assertTrue(Float.isNaN(TaskManagerState.rate(90,100,1000)));assertTrue(Float.isNaN(TaskManagerState.rate(200,100,0)));assertEquals(2048,TaskManagerState.rate(3072,1024,1000),.001);assertEquals(0,TaskManagerState.rate(3000,3000,5000),0);}
 @Test public void cpuUsesAvailableCapacity(){assertEquals(25,TaskManagerState.cpu(2000,1000,1000,4),.001);assertEquals(100,TaskManagerState.cpu(99999,0,1000,4),0);assertTrue(Float.isNaN(TaskManagerState.cpu(0,-1,1000,4)));assertTrue(Float.isNaN(TaskManagerState.cpu(50,100,1000,4)));assertTrue(Float.isNaN(TaskManagerState.cpu(100,0,1000,0)));}
 @Test public void missingMeasurementsStayLastInBothSortDirections(){assertTrue(TaskManagerState.compareMeasured(Double.NaN,10,true)>0);assertTrue(TaskManagerState.compareMeasured(Double.NaN,10,false)>0);assertTrue(TaskManagerState.compareMeasured(2,10,false)<0);assertTrue(TaskManagerState.compareMeasured(2,10,true)>0);assertEquals(0,TaskManagerState.compareMeasured(Double.NaN,Double.NaN,true));}
 @Test public void migratesLegacyPagesWithoutConfusingModernProcesses()throws Exception{TaskManagerState state=new TaskManagerState();state.restore(new JSONObject().put("tab","Processes"));assertEquals("Details",state.page);state.restore(new JSONObject().put("tab","Networking"));assertEquals("Performance",state.page);assertEquals("Network",state.resource);state.restore(new JSONObject().put("page","Processes").put("version",2));assertEquals("Processes",state.page);}
 @Test public void boundedStateRoundTripRetainsFilterAndChoices()throws Exception{TaskManagerState a=new TaskManagerState();a.page="Performance";a.resource="Network";a.query="a process";a.selected="pid:123";a.paused=true;a.interval=5000;a.navigation=0;TaskManagerState b=new TaskManagerState();b.restore(a.json());assertEquals(a.json().toString(),b.json().toString());b.restore(new JSONObject().put("page","invented").put("resource","Fake GPU").put("interval",1).put("query",String.join("",Collections.nCopies(500,"x"))));assertEquals("Processes",b.page);assertEquals("CPU",b.resource);assertEquals(2000,b.interval);assertEquals(256,b.query.length());}
 @Test public void malformedPortableChoicesAreRejected()throws Exception{Map<String,Object> values=new HashMap<>();values.put("taskmanager_theme","Dark");values.put("taskmanager_default_page","Details");values.put("taskmanager_speed",5000);TaskManagerState.validate(values);for(Object invalid:Arrays.asList(0,"5000",true)){values.put("taskmanager_speed",invalid);try{TaskManagerState.validate(values);fail("Invalid speed accepted");}catch(JSONException expected){}}values.put("taskmanager_speed",2000);values.put("taskmanager_theme","Night");try{TaskManagerState.validate(values);fail("Invalid theme accepted");}catch(JSONException expected){}}
}
